    if p_write and coalesce((coalesce((coalesce(((case when coalesce((em is not null), false) then em else '' end) = 'ravi@thefabricrush.com'), false) or coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'admin') = to_jsonb(true)), false)), false)), false) or coalesce((coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'repl') = to_jsonb(true)), false)), false) and coalesce((coalesce((coalesce((coalesce((not coalesce(coalesce(fp ? 'replTabs', false), false)), false) or coalesce((not coalesce(coalesce(jsonb_typeof((fp -> 'replTabs')) = 'array', false), false)), false)), false) or coalesce(((case when jsonb_typeof((fp -> 'replTabs')) = 'array' then jsonb_array_length((fp -> 'replTabs')) end) = 0), false)), false) or coalesce((jsonb_typeof((fp -> 'replTabs')) = 'array' and (fp -> 'replTabs') ?| array['repl', 'article', 'target', 'top', 'prod', 'follow', 'india']::text[]), false)), false)), false)), false) then return true; end if;
  end if;
  if p_coll = 'po' then   -- match /po/{doc}
    if true and coalesce((coalesce((coalesce(((case when coalesce((em is not null), false) then em else '' end) = 'ravi@thefabricrush.com'), false) or coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'admin') = to_jsonb(true)), false)), false)), false) or coalesce((coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'repl') = to_jsonb(true)), false)), false) and coalesce((coalesce((coalesce((coalesce((not coalesce(coalesce(fp ? 'replTabs', false), false)), false) or coalesce((not coalesce(coalesce(jsonb_typeof((fp -> 'replTabs')) = 'array', false), false)), false)), false) or coalesce(((case when jsonb_typeof((fp -> 'replTabs')) = 'array' then jsonb_array_length((fp -> 'replTabs')) end) = 0), false)), false) or coalesce((jsonb_typeof((fp -> 'replTabs')) = 'array' and (fp -> 'replTabs') ?| array['repl', 'article', 'target', 'top', 'prod', 'follow', 'india']::text[]), false)), false)), false)), false) then return true; end if;
  end if;
  if p_coll = 'packlist' then   -- match /packlist/{doc}
    if true and coalesce((coalesce((coalesce((coalesce(((case when coalesce((em is not null), false) then em else '' end) = 'ravi@thefabricrush.com'), false) or coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'admin') = to_jsonb(true)), false)), false)), false) or coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce(((fp -> 'repl') = to_jsonb(true)), false)), false)), false) or coalesce((coalesce((coalesce((em is not null), false) and coalesce((fp is not null), false)), false) and coalesce((coalesce(((fp -> 'fgiEntry') = to_jsonb(true)), false) or coalesce(((fp -> 'fgiEdit') = to_jsonb(true)), false)), false)), false)), false) then return true; end if;
