revoke all on function core.fs_can(text, text, text, boolean) from public, anon, authenticated;
grant execute on function core.fs_can(text, text, text, boolean) to service_role;

create or replace function core.fs_rights_many(p_cases jsonb) returns jsonb language sql stable security definer set search_path = core, public as $$
  select coalesce(jsonb_agg(core.fs_can(c->>'e', c->>'c', c->>'d', (c->>'w')::boolean) order by i), '[]'::jsonb)
    from jsonb_array_elements(p_cases) with ordinality t(c, i)
$$;
revoke all on function core.fs_rights_many(jsonb) from public, anon, authenticated;
grant execute on function core.fs_rights_many(jsonb) to service_role;

-- the reads: fs_get by the rule; fs_list keeps only the documents the person may read (the full list stays server-only)
do $do$ declare d text;
begin
  d := pg_get_functiondef('core.fs_get(text, text)'::regprocedure);
  d := regexp_replace(d, 'if not \(?core\.rt_reader\(\)[^\n]*?then raise exception ''fs_get: not an ERP sign-in''; end if;',
        'if auth.role() is distinct from ''service_role'' and not core.fs_can(core.me_email(), p_coll, p_id, false) then raise exception ''fs_get: permission denied''; end if;');
  if position('fs_can' in d) = 0 then raise exception 'fs_get: the sign-in check was not found'; end if;
  execute d;
  if to_regprocedure('core.fs_list_all(text)') is null then
    d := pg_get_functiondef('core.fs_list(text)'::regprocedure);
    d := replace(d, 'FUNCTION core.fs_list(', 'FUNCTION core.fs_list_all(');
    d := replace(d, 'if not core.rt_reader() then raise exception ''fs_list: not an ERP sign-in''; end if;', '');
    if position('fs_list_all' in d) = 0 or position('rt_reader' in d) > 0 then raise exception 'fs_list: could not be copied'; end if;
    execute d;
  end if;
end $do$;
revoke all on function core.fs_list_all(text) from public, anon, authenticated;
grant execute on function core.fs_list_all(text) to service_role;
create or replace function core.fs_list(p_coll text) returns jsonb language plpgsql stable security definer set search_path = core, public as $$
declare em text := core.me_email(); all_ jsonb := core.fs_list_all(p_coll);
begin
  if auth.role() = 'service_role' then return all_; end if;
  if em is null then raise exception 'fs_list: not an ERP sign-in'; end if;
  return coalesce((select jsonb_agg(x order by o) from jsonb_array_elements(all_) with ordinality t(x, o) where core.fs_can(em, p_coll, x->>'id', false)), '[]'::jsonb);
end $$;
revoke all on function core.fs_list(text) from public;
grant execute on function core.fs_list(text) to anon, authenticated, service_role;

-- the saves: a Firestore document by its rule (was: any staff)
do $do$ declare d text;
begin
  d := pg_get_functiondef('core.rt_save(jsonb, text)'::regprocedure);
  d := replace(d, 'and (not core.rt_reader() or (trim(both ''/'' from c->>''p'') ~ ''^fs/perms(/|$)'' and not core.rt_admin()))',
                  'and not core.fs_can(em, split_part(trim(both ''/'' from c->>''p''), ''/'', 2), split_part(trim(both ''/'' from c->>''p''), ''/'', 3), true)');
  d := replace(d, '(Firestore: staff only; access rights by an admin)', '(the same rule as Firestore)');
  if position('fs_can' in d) = 0 then raise exception 'rt_save: the Firestore check was not found'; end if;
  execute d;
end $do$;

notify pgrst, 'reload schema';
select case when position('fs_can' in pg_get_functiondef('core.fs_get(text, text)'::regprocedure)) > 0
             and position('fs_can' in pg_get_functiondef('core.rt_save(jsonb, text)'::regprocedure)) > 0
             and not has_function_privilege('anon', 'core.fs_list_all(text)', 'execute') then 'PASS' else 'FAIL' end as result;
